    private final Runnable tick=new Runnable(){public void run(){if(isFinishing()||isDestroyed())return;refresh();String pending=store.prefs.getString("device","");if(tab==2&&!pending.isEmpty()&&!polling&&System.currentTimeMillis()-lastPoll>=5000){lastPoll=System.currentTimeMillis();pollLogin(false);}handler.postDelayed(this,1000);}};

    @Override public void onCreate(Bundle state){
        int savedTheme=getSharedPreferences("settings",MODE_PRIVATE).getInt("theme",AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM);
        getDelegate().setLocalNightMode(savedTheme);super.onCreate(state);
        if(savedTheme==AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM)DynamicColors.applyToActivityIfAvailable(this,new DynamicColorsOptions.Builder().setThemeOverlay(com.google.android.material.R.style.ThemeOverlay_Material3_DynamicColors_DayNight).build());
        store=new Store(this);net=new Net(this,store);files=new Files(this,store);handler=new Handler(Looper.getMainLooper());
        if(state!=null){tab=state.getInt("tab",0);filter=state.getString("filter","");scope=state.getInt("scope",0);}else tab=getIntent().getIntExtra("tab",0);
        SyncNotifications.channels(this);PlaybackService.configure(this);build();Scheduler.apply(this,store);openRequestedSong(getIntent());
    }
