    private void buildProgress(){
        progressHost=new CoordinatorLayout(this);progressHost.setId(R.id.sync_host);footer.addView(progressHost,spaced(-1,-2,0,8));
        progressCard=Ui.card(this);progressCard.setId(R.id.sync_panel);progressCard.setCardBackgroundColor(color(R.color.surface_container));
        SwipeDismissBehavior<MaterialCardView> swipe=new SwipeDismissBehavior<MaterialCardView>(){@Override public boolean canSwipeDismissView(View view){return !SyncEngine.running.get()&&!busy;}};
        swipe.setSwipeDirection(SwipeDismissBehavior.SWIPE_DIRECTION_ANY);swipe.setDragDismissDistance(.35f);swipe.setStartAlphaSwipeDistance(.1f);swipe.setEndAlphaSwipeDistance(.6f);
        swipe.setListener(new SwipeDismissBehavior.OnDismissListener(){public void onDismiss(View view){dismissBanner();}public void onDragStateChanged(int state){}});
        CoordinatorLayout.LayoutParams params=new CoordinatorLayout.LayoutParams(-1,-2);params.setBehavior(swipe);progressHost.addView(progressCard,params);
        progressBody=Ui.column(this);progressBody.setPadding(dp(16),dp(8),dp(8),dp(14));progressCard.addView(progressBody);
        LinearLayout row=Ui.row(this),labels=Ui.column(this);progressTitle=text("Проверка избранного",14,R.color.on_surface,true);progressDetail=text("",12,R.color.on_surface_variant,false);Ui.ellipsis(progressDetail,1);labels.addView(progressTitle);labels.addView(progressDetail,spaced(-1,-2,4,0));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));
        progressCount=text("",12,R.color.on_surface_variant,true);row.addView(progressCount);stop=Ui.iconButton(this,R.drawable.ic_stop,"Остановить синхронизацию",false);stop.setBackgroundTintList(ColorStateList.valueOf(color(R.color.surface_container)));stop.setOnClickListener(v->{if(SyncEngine.running.get())stopSync();else if(store.prefs.getBoolean("needs_login",false))navigate(2);else startSync();});row.addView(stop);progressBody.addView(row);
        progress=new LinearProgressIndicator(this);progress.setTrackThickness(dp(4));progress.setTrackCornerRadius(dp(2));progress.setIndicatorColor(color(R.color.primary));progress.setTrackColor(color(R.color.outline_variant));progressBody.addView(progress,spaced(-1,4,4,0));progressCard.setOnClickListener(v->{if(!SyncEngine.running.get()&&store.prefs.getBoolean("needs_login",false))navigate(2);else syncDetails();});progressCard.setVisibility(View.GONE);
    }
    private String bannerKey(){return store.prefs.getString("last_outcome","")+":"+store.prefs.getLong("last_result_at",store.prefs.getLong("last_sync",0))+":"+store.prefs.getInt("last_missing",0)+":"+store.prefs.getBoolean("needs_login",false);}
    private void dismissBanner(){
        if(locked())return;String key=bannerKey();store.prefs.edit().putString("dismissed_banner_key",key).apply();refresh();
        Snackbar.make(root,"Уведомление скрыто",Snackbar.LENGTH_LONG).setAnchorView(navigation).setAction("Вернуть",v->{if(key.equals(store.prefs.getString("dismissed_banner_key","")))store.prefs.edit().remove("dismissed_banner_key").apply();refresh();}).show();
    }
