        miniCard=Ui.card(this);miniCard.setId(R.id.mini_player);miniCard.setCardBackgroundColor(color(R.color.surface_container));footer.addView(miniCard,spaced(-1,-2,0,8));miniBody=Ui.row(this);miniBody.setPadding(dp(10),dp(6),dp(6),dp(6));miniCard.addView(miniBody);
