    private void header(String title,String detail,boolean canSync){
        LinearLayout top=Ui.row(this);top.setPadding(dp(24),dp(20),dp(20),dp(16));LinearLayout labels=Ui.column(this);TextView heading=text(title,30,R.color.on_surface,true);ViewCompat.setAccessibilityHeading(heading,true);labels.addView(heading);summary=text(detail,13,R.color.on_surface_variant,false);labels.addView(summary,spaced(-1,-2,6,0));top.addView(labels,new LinearLayout.LayoutParams(0,-2,1));
        if(detail.isEmpty())summary.setVisibility(View.GONE);if(canSync){sync=Ui.iconButton(this,R.drawable.ic_sync,"Синхронизировать избранное",true);sync.setId(R.id.sync_button);sync.setOnClickListener(v->startSync());top.addView(sync);}content.addView(top);
    }
    private void renderTab(boolean animate){
        content.removeAllViews();summary=null;stamp=null;sync=null;choose=null;login=null;folderLabel=null;intervalLabel=null;themeLabel=null;auto=null;wifi=null;lyrics=null;results=null;library=null;adapter=null;empty=null;codeLabel=null;codeCard=null;accountStatus=null;accountNameLabel=null;avatarLabel=null;archiveClear=null;
        if(tab==0)libraryTab();else if(tab==1)settingsTab();else accountTab();
        if(animate){content.setAlpha(0);content.animate().alpha(1).setDuration(150).start();}refresh();
    }
    private void libraryTab(){
        header("Моя музыка",allRows.isEmpty()?"Избранное из Яндекс Музыки":Ui.tracks(allRows.size()),true);
        LinearLayout tools=Ui.column(this);tools.setPadding(dp(20),0,dp(20),0);
        MaterialCardView searchBox=Ui.card(this);searchBox.setRadius(dp(28));searchBox.setCardBackgroundColor(color(R.color.surface_container));LinearLayout searchRow=Ui.row(this);searchRow.setPadding(dp(16),0,dp(4),0);searchBox.addView(searchRow,new FrameLayout.LayoutParams(-1,dp(56)));
        ImageView searchIcon=new ImageView(this);searchIcon.setId(R.id.search_icon);searchIcon.setImageResource(R.drawable.ic_search);searchIcon.setImageTintList(ColorStateList.valueOf(color(R.color.on_surface_variant)));searchIcon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);searchRow.addView(searchIcon,new LinearLayout.LayoutParams(dp(24),dp(24)));
        AppCompatEditText search=new AppCompatEditText(this);search.setId(R.id.search);search.setBackground(null);search.setInputType(InputType.TYPE_CLASS_TEXT);search.setSingleLine(true);search.setGravity(Gravity.CENTER_VERTICAL);search.setIncludeFontPadding(false);search.setPadding(dp(12),0,0,0);search.setTextSize(16);search.setTextColor(color(R.color.on_surface));search.setHintTextColor(color(R.color.on_surface_variant));search.setHint("Поиск по библиотеке");search.setContentDescription("Поиск по библиотеке");search.setText(filter);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);searchRow.addView(search,new LinearLayout.LayoutParams(0,-1,1));
        MaterialButton clear=Ui.iconButton(this,R.drawable.ic_close,"Очистить поиск",false);clear.setId(R.id.search_clear);clear.setBackgroundTintList(ColorStateList.valueOf(color(R.color.surface_container)));clear.setVisibility(filter.isEmpty()?View.GONE:View.VISIBLE);clear.setOnClickListener(v->search.setText(""));searchRow.addView(clear);tools.addView(searchBox);
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){filter=s.toString();clear.setVisibility(s.length()==0?View.GONE:View.VISIBLE);applyFilter();}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,a,event)->{hideKeyboard();search.clearFocus();return true;});
        HorizontalScrollView horizontal=new HorizontalScrollView(this);horizontal.setHorizontalScrollBarEnabled(false);ChipGroup group=new ChipGroup(this);group.setSingleLine(true);group.setSingleSelection(true);group.setSelectionRequired(true);group.setChipSpacingHorizontal(dp(6));String[] filters={"Все","Скачано","Не скачано","Архив"};int[] filterIds={R.id.filter_all,R.id.filter_downloaded,R.id.filter_missing,R.id.filter_archive};for(int n=0;n<4;n++){int index=n;Chip chip=new Chip(this,null,com.google.android.material.R.attr.chipStyle);chip.setId(filterIds[n]);chip.setText(filters[n]);chip.setTextSize(13);chip.setChipStartPadding(dp(10));chip.setChipEndPadding(dp(10));chip.setTextStartPadding(0);chip.setTextEndPadding(0);chip.setMinWidth(dp(48));chip.setCheckable(true);chip.setChecked(n==scope);chip.setCheckedIconVisible(false);chip.setEnsureMinTouchTargetSize(true);chip.setMinHeight(dp(48));chip.setOnClickListener(v->{scope=index;applyFilter();refresh();});group.addView(chip);}horizontal.addView(group);tools.addView(horizontal,spaced(-1,52,8,2));
        archiveClear=Ui.button(this,"Очистить архив",R.drawable.ic_close,false);archiveClear.setId(R.id.archive_clear);archiveClear.setStrokeWidth(0);archiveClear.setOnClickListener(v->removeArchive(null));tools.addView(archiveClear,spaced(-1,48,0,4));content.addView(tools);
        FrameLayout frame=new FrameLayout(this);content.addView(frame,new LinearLayout.LayoutParams(-1,0,1));library=new RecyclerView(this);library.setId(R.id.library_list);library.setLayoutManager(new LinearLayoutManager(this));library.setClipToPadding(false);library.setPadding(dp(12),dp(2),dp(12),dp(12));adapter=new LibraryAdapter();adapter.setHasStableIds(true);library.setAdapter(adapter);library.setItemAnimator(null);frame.addView(library,new FrameLayout.LayoutParams(-1,-1));
        empty=Ui.column(this);empty.setId(R.id.library_empty);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(32),dp(16),dp(32),dp(16));frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));applyFilter();
    }
    private ScrollView scroll(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);scroll.setClipToPadding(false);scroll.setPadding(dp(20),0,dp(20),dp(24));LinearLayout panel=Ui.column(this);scroll.addView(panel,new ScrollView.LayoutParams(-1,-2));content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));return scroll;}
    private void section(LinearLayout panel,String name){TextView label=text(name,13,R.color.on_surface_variant,true);ViewCompat.setAccessibilityHeading(label,true);label.setPadding(dp(4),0,0,0);add(panel,label,20,10);}
    private LinearLayout group(LinearLayout panel){MaterialCardView card=Ui.card(this);LinearLayout body=Ui.column(this);body.setPadding(dp(4),dp(4),dp(4),dp(4));card.addView(body);add(panel,card,0,0);return body;}
    private LinearLayout settingRow(LinearLayout panel,int icon,String title,String description,boolean arrow){
        LinearLayout row=Ui.row(this);row.setPadding(dp(16),dp(12),dp(8),dp(12));row.setMinimumHeight(dp(72));ImageView image=new ImageView(this);image.setImageResource(icon);image.setImageTintList(ColorStateList.valueOf(color(R.color.on_surface_variant)));row.addView(image,new LinearLayout.LayoutParams(dp(24),dp(24)));
        LinearLayout labels=Ui.column(this);labels.setPadding(dp(16),0,dp(8),0);TextView heading=text(title,16,R.color.on_surface,false);labels.addView(heading);if(description!=null){TextView detail=text(description,13,R.color.on_surface_variant,false);Ui.ellipsis(detail,2);labels.addView(detail,spaced(-1,-2,4,0));}row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));
        if(arrow){ImageView chevron=new ImageView(this);chevron.setImageResource(R.drawable.ic_chevron);chevron.setImageTintList(ColorStateList.valueOf(color(R.color.on_surface_variant)));row.addView(chevron,new LinearLayout.LayoutParams(dp(24),dp(24)));}
        row.setBackgroundResource(android.R.attr.selectableItemBackground==0?0:resolve(android.R.attr.selectableItemBackground));panel.addView(row,new LinearLayout.LayoutParams(-1,-2));return row;
    }
    private int resolve(int attr){android.util.TypedValue value=new android.util.TypedValue();getTheme().resolveAttribute(attr,value,true);return value.resourceId;}
    private TextView rowDetail(LinearLayout row){LinearLayout labels=(LinearLayout)row.getChildAt(1);return (TextView)labels.getChildAt(1);}
    private MaterialSwitch switchRow(LinearLayout panel,int icon,String title,String detail,String preference,boolean defaultValue){
        LinearLayout row=settingRow(panel,icon,title,detail,false);MaterialSwitch control=new MaterialSwitch(this);control.setContentDescription(title);control.setChecked(store.prefs.getBoolean(preference,defaultValue));control.setMinimumWidth(dp(52));row.addView(control);row.setOnClickListener(v->{if(control.isEnabled())control.setChecked(!control.isChecked());});return control;
    }
    private void settingsTab(){
        header("Настройки","",false);ScrollView scroll=scroll();scroll.setId(R.id.settings_scroll);LinearLayout panel=(LinearLayout)scroll.getChildAt(0);
        LinearLayout storage=group(panel);LinearLayout folder=settingRow(storage,R.drawable.ic_folder,"Папка сохранения",folderName(),true);folder.setId(R.id.folder_button);folderLabel=rowDetail(folder);folder.setOnClickListener(v->{if(!locked())pickFolder();});
        section(panel,"Синхронизация");LinearLayout syncing=group(panel);
        auto=switchRow(syncing,R.drawable.ic_sync,"Автосинхронизация",null,"auto",false);auto.setId(R.id.auto_switch);
        auto.setOnCheckedChangeListener((b,on)->{if(changing)return;if(on&&!ready()){changing=true;auto.setChecked(false);changing=false;snack("Сначала войди в аккаунт и выбери папку");return;}store.prefs.edit().putBoolean("auto",on).commit();Scheduler.apply(this,store);refresh();});
        intervalRow=settingRow(syncing,R.drawable.ic_clock,"Проверять избранное",intervalName(),true);intervalLabel=rowDetail((LinearLayout)intervalRow);intervalRow.setOnClickListener(v->intervalDialog());
        wifi=switchRow(syncing,R.drawable.ic_wifi,"Только Wi-Fi",null,"wifi",false);wifi.setId(R.id.wifi_switch);wifiRow=(View)wifi.getParent();wifi.setOnCheckedChangeListener((b,on)->{store.prefs.edit().putBoolean("wifi",on).commit();Scheduler.apply(this,store);});
        section(panel,"Файлы");LinearLayout fileOptions=group(panel);lyrics=switchRow(fileOptions,R.drawable.ic_lyrics,"Тексты песен","Сохранять .txt и .lrc","lyrics",true);lyrics.setId(R.id.lyrics_switch);lyrics.setOnCheckedChangeListener((b,on)->store.prefs.edit().putBoolean("lyrics",on).commit());
        LinearLayout retry=settingRow(fileOptions,R.drawable.ic_sync,"Обновить обложки и тексты",null,true);retry.setOnClickListener(v->{if(locked())return;store.getWritableDatabase().execSQL("UPDATE tracks SET cover=CASE WHEN cover='unavailable' THEN 'pending' ELSE cover END,lyrics=CASE WHEN lyrics='unavailable' THEN 'pending' ELSE lyrics END");Store.revision.incrementAndGet();startSync();});
        section(panel,"Оформление");LinearLayout appearance=group(panel);LinearLayout theme=settingRow(appearance,R.drawable.ic_theme,"Тема",themeName(),true);theme.setId(R.id.theme_button);themeLabel=rowDetail(theme);theme.setOnClickListener(v->themeDialog());
        section(panel,"Уведомления и фон");LinearLayout system=group(panel);results=switchRow(system,R.drawable.ic_notifications,"Итоги синхронизации",null,"notify_results",true);results.setOnCheckedChangeListener((b,on)->{store.prefs.edit().putBoolean("notify_results",on).apply();if(on)askNotifications(false);});
        settingRow(system,R.drawable.ic_notifications,"Настройки уведомлений",notificationsAllowed()?"Разрешены":"Выключены на телефоне",true).setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));
        settingRow(system,R.drawable.ic_battery,"Работа в фоне","Настройки телефона",true).setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));
        TextView version=text("Моя музыка · 2.0.1",12,R.color.on_surface_variant,false);version.setGravity(Gravity.CENTER);add(panel,version,28,0);
    }
    private String folderName(){String tree=store.prefs.getString("tree","");if(tree.isEmpty())return "Выбрать папку";try{String id=DocumentsContract.getTreeDocumentId(Uri.parse(tree));int colon=id.indexOf(':');String path=colon>=0?id.substring(colon+1):id;return path.isEmpty()?files.display(tree):path;}catch(Exception e){return files.display(tree);}}
    private String intervalName(){int h=store.prefs.getInt("hours",6);return h==1?"Каждый час":h==24?"Раз в день":"Каждые 6 часов";}
    private String themeName(){int value=store.prefs.getInt("theme",AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM);return value==AppCompatDelegate.MODE_NIGHT_YES?"Тёмная":value==AppCompatDelegate.MODE_NIGHT_NO?"Светлая":"От телефона";}
